// AnalyzeFile analyzes one lockfile from in-memory content. The Fanal version
// used here exposes library analysis through a FileMap, so pass a one-file map
// to preserve the path while keeping each lockfile's results isolated.
func AnalyzeFile(path string, _ os.FileInfo, content []byte) ([]types.Application, error) {
	return analyzer.GetLibraries(extractor.FileMap{path: content})
}

func convertLibWithScanner(path string, apps []types.Application) ([]models.LibraryScanner, error) {
	scanners := []models.LibraryScanner{}
	for _, app := range apps {
		libs := []trivyTypes.Library{}
		for _, lib := range app.Libraries {
			libs = append(libs, trivyTypes.Library{
				Name:    lib.Library.Name,
				Version: lib.Library.Version,
			})
		}
		filePath := path
		if filePath == "" {
			filePath = app.FilePath
		}
		scanners = append(scanners, models.LibraryScanner{
			Path: filePath,
			Libs: libs,
		})
	}
	return scanners, nil
}
